import { operation, resource } from "@tinker/core";
import type { DatabaseConnection, TransactionSettings } from "kysely";

import { database, transaction } from "~/components/database-sqlite/index.server";
import { requestHeaders } from "~/components/requests/index.server";
import { createAccountStream, publishAccountNotice } from "~/components/sync-sqlite/index.server";

import { betterAuthModule, betterAuthStart, kyselyModule, nodeSqliteDialect } from "./modules";
import { codeSignin, mcpProvider } from "./plugins.server";
import { authRateLimit, authSettings } from "./settings.server";

/** The Postgres `session` trigger has no trigger here: each committed change says so itself. */
const publishSessionChange = operation({
  label: "auth.sessionChange",
  depends: { transaction },
  run: async ({ transaction }) => {
    await transaction.notify("start_sync", "session");
  },
});

/**
 * Better Auth's driver over the app's write connection, with its one checkout waiting for the
 * process's write turn. `node:sqlite` is synchronous and a session transaction stays open
 * across awaits, so a free-running writer would land inside another call's transaction.
 */
const authDriver = resource({
  label: "auth.driver",
  depends: { database, dialect: nodeSqliteDialect },
  factory: async ({ database, dialect }) => {
    const driver = new dialect.NodeSqliteDialect({ database: database.client }).createDriver();
    const turns = new Map<DatabaseConnection, () => void>();

    return {
      async init() {
        await driver.init();
      },
      async destroy() {
        // The database resource owns the connection and closes it with the scope.
      },
      async acquireConnection() {
        const release = await database.writeTurn();

        try {
          const connection = await driver.acquireConnection();

          turns.set(connection, release);

          return connection;
        } catch (error) {
          release();

          throw error;
        }
      },
      async releaseConnection(connection: DatabaseConnection) {
        try {
          await driver.releaseConnection(connection);
        } finally {
          turns.get(connection)?.();
          turns.delete(connection);
        }
      },
      async beginTransaction(connection: DatabaseConnection, settings: TransactionSettings) {
        await driver.beginTransaction(connection, settings);
      },
      async commitTransaction(connection: DatabaseConnection) {
        await driver.commitTransaction(connection);
      },
      async rollbackTransaction(connection: DatabaseConnection) {
        await driver.rollbackTransaction(connection);
      },
    };
  },
});

/**
 * A session delete sends the account notice after its commit: sign-out, a revoked or deleted
 * session, and a deleted user (its sessions go through the same delete) all end here.
 * The SQLite set has no mail component, so sign-in is the only email-password flow: no reset
 * mail and no verification mail. A code sign-in marks its session with the code, the browser,
 * and the OAuth client that approved it; the stock device routes are off, as the component
 * serves its own.
 */
export const auth = resource({
  label: "auth",
  depends: {
    database,
    settings: authSettings,
    limits: authRateLimit,
    writer: authDriver,
    dialect: nodeSqliteDialect,
    kysely: kyselyModule,
    created: createAccountStream,
    deleted: publishAccountNotice,
    changed: publishSessionChange,
    auth: betterAuthModule,
    start: betterAuthStart,
    codes: codeSignin,
    oauth: mcpProvider,
  },
  factory: async (
    {
      database,
      settings,
      limits,
      writer,
      dialect,
      kysely,
      created,
      deleted,
      changed,
      auth,
      start,
      codes,
      oauth,
    },
    { closing, log },
  ) => {
    const { Kysely } = kysely;
    const base = new dialect.NodeSqliteDialect({ database: database.client });

    const db = new Kysely({
      dialect: {
        createDriver: () => writer,
        createAdapter: () => base.createAdapter(),
        createQueryCompiler: () => base.createQueryCompiler(),
        createIntrospector: (instance) => base.createIntrospector(instance),
      },
    });

    const { betterAuth } = auth;
    const { tanstackStartCookies } = start;

    const instance = betterAuth({
      baseURL: settings.origin,
      secret: settings.secret,
      database: { db, type: "sqlite" },
      session: {
        deferSessionRefresh: true,
        additionalFields: {
          signinCode: { type: "string", required: false, input: false },
          signinBrowser: { type: "string", required: false, input: false },
          signinApprovedBy: { type: "string", required: false, input: false },
        },
      },
      disabledPaths: [
        "/device/code",
        "/device/token",
        "/device",
        "/device/approve",
        "/device/deny",
      ],
      databaseHooks: {
        user: {
          create: {
            after: async ({ id }) => {
              try {
                await created.run({ input: { accountId: id }, signal: closing });
              } catch (error) {
                log.error("auth.accountStreamFailed", { accountId: id, error: String(error) });
              }
            },
          },
        },
        session: {
          create: {
            after: async ({ userId }) => {
              await created.run({ input: { accountId: userId }, signal: closing });
              await changed.run({ signal: closing });
            },
          },
          update: {
            after: () => changed.run({ signal: closing }),
          },
          delete: {
            after: async ({ userId }) => {
              // The Postgres trigger spoke before the account notice; keep that order.
              await changed.run({ signal: closing });
              await deleted.run({ rawInput: { accountId: userId }, signal: closing });
            },
          },
        },
      },
      emailAndPassword: {
        enabled: true,
      },
      hooks: { before: oauth.clientCheck },
      // Where the limiter is on (production, by Better Auth's default), a code start is held to
      // 5 per IP in 10 minutes; every other path keeps Better Auth's own limits.
      rateLimit: {
        enabled: limits.enabled,
        customRules: { "/signin/code": { window: 600, max: 5 } },
      },
      plugins: [...oauth.plugins, ...codes, tanstackStartCookies()],
    });

    // Plugin start-up writes (the OAuth provider seeds its MCP resource row) end before the
    // resource is ready, so a scope that closes early never closes the database under them.
    await instance.$context;

    return instance;
  },
});

export const principal = resource({
  label: "request.principal",
  target: "session",
  depends: { auth, headers: requestHeaders },
  factory: async ({ auth, headers }) =>
    (
      await auth.api.getSession({
        headers,
        query: { disableCookieCache: true, disableRefresh: true },
      })
    )?.user ?? null,
});

/** A long stream rechecks the live cookie without using caches or refreshing the session. */
export const liveAccount = operation({
  label: "sync.liveAccount",
  depends: { auth, headers: requestHeaders },
  run: async ({ auth, headers }) =>
    (
      await auth.api.getSession({
        headers,
        query: { disableCookieCache: true, disableRefresh: true },
      })
    )?.user.id ?? null,
});

import { operation } from "@tinker/core";
import { z } from "zod";

import { auth } from "./auth.server";

/**
 * ADR 0103's named protocol exception: the app's auth library owns its HTTP contract, so this
 * operation hands it the whole request and returns its reply as is.
 */
export const handleAuth = operation({
  label: "handleAuth",
  input: z.instanceof(Request),
  depends: { auth },
  run: ({ auth }, { input }) => auth.handler(input),
});

export { auth, principal, liveAccount } from "./auth.server";
export { handleAuth } from "./handle.server";
export { checkMcpToken, checkMcpTokenInput, mcpCaller } from "./mcp.server";
export { authMcp, authRateLimit, authSettings, authStartup } from "./settings.server";

export {
  approveSignin,
  approveSigninInput,
  endSignin,
  endSigninInput,
  listSignins,
  listSigninsInput,
} from "./signin.server";

export { openSync, eventStream } from "./stream.server";

import { operation, tag } from "@tinker/core";
import { z } from "zod";

import { auth } from "./auth.server";
import { betterAuthApi, betterAuthOAuth2, oauthProviderModule } from "./modules";
import { authMcp, authSettings } from "./settings.server";

/** The person and OAuth client an MCP call speaks for; the app binds it per call. */
export const mcpCaller = tag({
  label: "auth.mcpCaller",
  parse: z.object({
    userId: z.string().min(1),
    clientId: z.string().min(1),
    scopes: z.array(z.string()),
  }),
});

/** The claims a checked access token must carry; `scope` is a space-separated list. */
const tokenClaims = z.object({
  sub: z.string().min(1),
  azp: z.string().min(1),
  scope: z.string().default(""),
});

/** The user and the OAuth client a token names must both exist; the client must be enabled. */
const liveRows = z.object({
  user: z.object({ id: z.string() }),
  client: z.object({
    disabled: z
      .boolean()
      .nullable()
      .optional()
      .refine((off) => !off),
  }),
});

/**
 * The parts of an MCP request a token check reads, as Better Auth's `requestToResourceInput`
 * names them. The route reads them off its `Request`; replies stay with the route too.
 */
export const checkMcpTokenInput = z.object({
  authorizationHeader: z.string().nullable(),
  dpopProofJwt: z.string().nullable(),
  method: z.string(),
  url: z.url(),
});

/**
 * Check the bearer token of an MCP request: Better Auth's own resource-server steps
 * (`verifyAccessTokenRequest` in `@better-auth/mcp`'s `createMcpProtectedRequestHandler`), with
 * the key set read from this auth instance instead of fetched over HTTP from our own `/jwks`.
 * The answer is the caller, or the challenge for the route to send: the RFC 9728 401 (403 for a
 * missing scope), with the same headers and JSON-RPC body `@better-auth/mcp` sends.
 */
export const checkMcpToken = operation({
  label: "auth.checkMcpToken",
  input: checkMcpTokenInput,
  depends: {
    auth,
    settings: authSettings,
    mcp: authMcp,
    api: betterAuthApi,
    oauth2: betterAuthOAuth2,
    provider: oauthProviderModule,
  },
  run: async ({ auth, settings, mcp, api, oauth2, provider }, { input }) => {
    const { APIError } = api;

    const resource = new URL(mcp.path, settings.origin).href;

    // offline_access is for the token endpoint (a refresh token), not for the resource.
    const required = mcp.scopes.filter((scope) => scope !== "offline_access");

    const context = await auth.$context;

    try {
      const authorization = oauth2.parseAccessTokenAuthorization(input.authorizationHeader) ?? {
        scheme: "Unknown",
        token: "",
      };

      if (authorization.scheme === "Unknown") {
        throw new APIError("UNAUTHORIZED", { message: "missing authorization header" });
      }

      // Read before the check, so a failure inside the check is the token's, not the database's.
      const keys = await auth.api.getJwks();

      const payload = await oauth2
        .verifyJwsAccessToken(authorization.token, {
          jwksFetch: async () => keys,
          verifyOptions: {
            issuer: context.baseURL,
            audience: resource,
            requiredClaims: ["exp", "iat"],
          },
        })
        .catch(() => {
          throw new APIError("UNAUTHORIZED", { message: "invalid access token" });
        });

      // A token with no person behind it (no `sub`) speaks for no one here.
      const claims = tokenClaims.safeParse(payload);

      if (!claims.success) {
        throw new APIError("UNAUTHORIZED", { message: "access token names no user" });
      }

      // The token is a JWT with no store behind it: one read stops a deleted user or client, and
      // a disabled client, at once. A sign-out or a revoke ends at the token's 5-minute end.
      const [user, client] = await Promise.all([
        context.internalAdapter.findUserById(claims.data.sub),
        context.adapter.findOne({
          model: "oauthClient",
          where: [{ field: "clientId", value: claims.data.azp }],
        }),
      ]);

      if (!liveRows.safeParse({ user, client }).success) {
        throw new APIError("UNAUTHORIZED", {
          message: "access token speaks for no live user or app",
        });
      }

      const scopes = claims.data.scope.split(" ").filter(Boolean);

      const missing = required.filter((scope) => !scopes.includes(scope));

      if (missing.length > 0) throw oauth2.createInsufficientScopeError(missing);

      await oauth2
        .enforceDpopBinding({
          payload,
          authorization,
          proofJwt: input.dpopProofJwt,
          method: input.method,
          url: input.url,
          replayStore: oauth2.createDpopReplayStore(context.internalAdapter),
        })
        .catch((error: unknown) => {
          if (!oauth2.isDpopBindingError(error)) throw error;

          throw new APIError("UNAUTHORIZED", {
            message: error.message,
            error: error.code,
            error_description: error.message,
          });
        });

      return {
        caller: { userId: claims.data.sub, clientId: claims.data.azp, scopes },
      };
    } catch (error) {
      const challenge = provider.createResourceServerChallenge(error, resource, {
        challengeScopes: required,
      });

      if (!challenge) throw error;

      const headers = new Headers(challenge.headers);

      headers.set("Content-Type", "application/json");

      return {
        challenge: {
          status: challenge.statusCode,
          headers: Object.fromEntries(headers),
          body: { jsonrpc: "2.0", error: { code: -32000, message: challenge.message }, id: null },
        },
      };
    }
  },
});

import { resource } from "@tinker/core";

export const betterAuthModule = resource({
  label: "module:better-auth",
  target: "scope",
  factory: () => import("better-auth"),
});

export const betterAuthStart = resource({
  label: "module:better-auth/tanstack-start",
  target: "scope",
  factory: () => import("better-auth/tanstack-start"),
});

/** Better Auth's Kysely adapter owns the SQL over `node:sqlite`, so Kysely is a dep. */
export const kyselyModule = resource({
  label: "module:kysely",
  target: "scope",
  factory: () => import("kysely"),
});

export const nodeSqliteDialect = resource({
  label: "module:@better-auth/kysely-adapter/node-sqlite-dialect",
  target: "scope",
  factory: () => import("@better-auth/kysely-adapter/node-sqlite-dialect"),
});

/** Endpoints, hooks, and errors for the component's own small plugins. */
export const betterAuthApi = resource({
  label: "module:better-auth/api",
  target: "scope",
  factory: () => import("better-auth/api"),
});

/** `setSessionCookie`: a code sign-in sets the same cookie as a password sign-in. */
export const betterAuthCookies = resource({
  label: "module:better-auth/cookies",
  target: "scope",
  factory: () => import("better-auth/cookies"),
});

/** The resource-server half: check an access token against a key set we hold. */
export const betterAuthOAuth2 = resource({
  label: "module:better-auth/oauth2",
  target: "scope",
  factory: () => import("better-auth/oauth2"),
});

/** Signs the OAuth access tokens; its key set checks them. */
export const jwtModule = resource({
  label: "module:better-auth/plugins/jwt",
  target: "scope",
  factory: () => import("better-auth/plugins/jwt"),
});

/** RFC 8628: the `deviceCode` table, user codes, and the one-use redeem. */
export const deviceAuthorizationModule = resource({
  label: "module:better-auth/plugins/device-authorization",
  target: "scope",
  factory: () => import("better-auth/plugins/device-authorization"),
});

/** The OAuth 2.1 provider set up for MCP, with RFC 9728 metadata. */
export const mcpModule = resource({
  label: "module:@better-auth/mcp",
  target: "scope",
  factory: () => import("@better-auth/mcp"),
});

/** The provider under `mcp()`: its RFC 9728 challenge for a refused token. */
export const oauthProviderModule = resource({
  label: "module:@better-auth/oauth-provider",
  target: "scope",
  factory: () => import("@better-auth/oauth-provider"),
});

import { resource } from "@tinker/core";
import type { BetterAuthPlugin } from "better-auth";
import { z } from "zod";

import {
  betterAuthApi,
  betterAuthCookies,
  deviceAuthorizationModule,
  jwtModule,
  mcpModule,
} from "./modules";
import { authMcp, authSettings } from "./settings.server";

/** RFC 8628 6.1: no vowels and no look-alike letters, so a code is easy to read out. */
const letters = "BCDFGHJKLMNPQRSTVWXZ";

/** The one device client: the browser that asks for a code. */
export const webClient = "web";

/** A code waits 10 minutes; at most 50 wait at once. */
export const codeSeconds = 600;

const waitingCap = 50;

/** One leading slash, then no slash or backslash; no control character, space, or backslash. */
const sitePath = /^\/(?![/\\])[^\\\s\p{Cc}]*$/u;

/** The first match names the browser; Chrome's agent also says Safari, so Chrome comes first. */
const browsers = [
  [/Edg\//, "Edge"],
  [/CriOS|Chrome\//, "Chrome"],
  [/FxiOS|Firefox\//, "Firefox"],
  [/Safari\//, "Safari"],
] as const;

const systems = [
  [/iPhone|iPad/, "iPhone or iPad"],
  [/Android/, "Android"],
  [/Mac OS X/, "Mac"],
  [/Windows/, "Windows"],
  [/Linux/, "Linux"],
] as const;

/**
 * Sign-in with a code, RFC 8628 turned around: the browser asks for a code and keeps the device
 * half in an httpOnly cookie, a signed-in caller approves the code (`approveSignin`), and only
 * that browser finishes. Better Auth's `deviceAuthorization` owns the table, the user codes, and
 * the one-use redeem; its public `/device*` routes are off, so these three routes are the way in.
 * The finish sets the session cookie through Better Auth, so a start from the OAuth login page
 * (with its signed `oauth_query`) goes on to the OAuth redirect through the provider's own hook.
 */
export const codeSignin = resource({
  label: "auth.codeSignin",
  target: "scope",
  depends: {
    settings: authSettings,
    api: betterAuthApi,
    cookies: betterAuthCookies,
    device: deviceAuthorizationModule,
  },
  factory: async ({ settings, api, cookies, device }) => {
    const { APIError, createAuthEndpoint } = api;
    const { setSessionCookie } = cookies;
    const { deviceAuthorization, redeemDeviceCode } = device;

    const secure = settings.origin.startsWith("https:");

    const half = { httpOnly: true, sameSite: "lax", path: "/", secure } as const;

    // On https the `__Host-` prefix keeps a sibling subdomain from planting its own device half.
    const deviceCookie = secure ? "__Host-tinker_device" : "tinker_device";

    const origin = new URL(settings.origin).origin;

    const codes = deviceAuthorization({
      expiresIn: `${codeSeconds}s`,
      validateClient: (clientId) => clientId === webClient,
      generateUserCode: () => {
        const picked: string[] = [];

        // Drop bytes past the last whole run of 20 letters, so each letter is as likely.
        while (picked.length < 8) {
          for (const byte of crypto.getRandomValues(new Uint8Array(16))) {
            if (byte < 240 && picked.length < 8) picked.push(letters[byte % 20]);
          }
        }

        return picked.join("");
      },
    });

    const signin = {
      id: "tinker-code-signin",
      schema: {
        deviceCode: {
          fields: {
            signinBrowser: { type: "string", required: false, input: false },
            signinNext: { type: "string", required: false, input: false },
            signinClient: { type: "string", required: false, input: false },
            signinClientId: { type: "string", required: false, input: false },
            signinApprovedBy: { type: "string", required: false, input: false },
          },
        },
      },
      endpoints: {
        startCodeSignin: createAuthEndpoint(
          "/signin/code",
          {
            method: "POST",
            body: z.object({
              // Obelisk's safeNext, and the browser's own reading must stay on this site.
              next: z
                .string()
                .max(2000)
                .regex(sitePath)
                .refine((next) => new URL(next, origin).origin === origin)
                .catch("/"),
              oauth_query: z.string().max(8000).optional(),
            }),
            metadata: { noStore: true },
          },
          async (ctx) => {
            const { adapter } = ctx.context;

            // Obelisk swept ended codes each minute; here each start sweeps them first.
            await adapter.deleteMany({
              model: "deviceCode",
              where: [{ field: "expiresAt", operator: "lte", value: new Date() }],
            });

            const waiting = await adapter.count({
              model: "deviceCode",
              where: [{ field: "expiresAt", operator: "gt", value: new Date() }],
            });

            if (waiting >= waitingCap) {
              throw new APIError("TOO_MANY_REQUESTS", {
                error: "slow_down",
                error_description: "Too many codes wait now. Try again in 10 minutes.",
              });
            }

            const started = await codes.endpoints.deviceCode({
              context: ctx.context,
              headers: ctx.headers,
              body: { client_id: webClient },
            });

            // The provider's own before-hook has checked the signature of `oauth_query`.
            const query = new URLSearchParams(ctx.body.oauth_query);

            const client = await adapter.findOne<{ name?: string | null }>({
              model: "oauthClient",
              where: [{ field: "clientId", value: query.get("client_id") ?? "" }],
            });

            // The browser and system in plain words, as obelisk shows them.
            const agent = new Headers(ctx.headers).get("user-agent") ?? "";

            const [browser = "a browser"] = browsers
              .filter(([pattern]) => pattern.test(agent))
              .map(([, name]) => name);

            const [system = "a device"] = systems
              .filter(([pattern]) => pattern.test(agent))
              .map(([, name]) => name);

            // An OAuth start names its client; a plain sign-in names none.
            await adapter.update({
              model: "deviceCode",
              where: [{ field: "deviceCode", value: started.device_code }],
              update: {
                signinBrowser: `${browser} on ${system}`,
                signinNext: ctx.body.next,
                signinClient: client && (client.name ?? "an app"),
                signinClientId: query.get("client_id"),
              },
            });

            ctx.setCookie(deviceCookie, started.device_code, { ...half, maxAge: codeSeconds });

            return ctx.json({
              user_code: `${started.user_code.slice(0, 4)}-${started.user_code.slice(4)}`,
              expires_in: started.expires_in,
            });
          },
        ),
        codeSigninState: createAuthEndpoint(
          "/signin/code/state",
          { method: "GET", metadata: { noStore: true } },
          async (ctx) => {
            // No device code is empty, so a missing cookie finds no row.
            const value = ctx.getCookie(deviceCookie) ?? "";

            const row = await ctx.context.adapter.findOne<{ status: string; expiresAt: Date }>({
              model: "deviceCode",
              where: [
                { field: "deviceCode", value },
                { field: "clientId", value: webClient },
              ],
            });

            if (!row || row.expiresAt <= new Date()) return ctx.json({ state: "gone" });

            return ctx.json({ state: row.status === "approved" ? "approved" : "waiting" });
          },
        ),
        finishCodeSignin: createAuthEndpoint(
          "/signin/code/finish",
          {
            method: "POST",
            body: z.object({ oauth_query: z.string().max(8000).optional() }),
            metadata: { noStore: true },
          },
          async (ctx) => {
            const value = ctx.getCookie(deviceCookie) ?? "";

            const row = await ctx.context.adapter.findOne<{
              status: string;
              expiresAt: Date;
              userCode: string;
              signinNext: string;
              signinBrowser: string | null;
              signinClientId: string | null;
              signinApprovedBy: string | null;
            }>({
              model: "deviceCode",
              where: [
                { field: "deviceCode", value },
                { field: "clientId", value: webClient },
              ],
            });

            if (!row || row.expiresAt <= new Date()) {
              ctx.setCookie(deviceCookie, "", { ...half, maxAge: 0 });
              ctx.setStatus(410);

              return ctx.json({ state: "gone" });
            }

            // The OAuth request goes on only for the client the start named, and the approver saw.
            if (new URLSearchParams(ctx.body.oauth_query).get("client_id") !== row.signinClientId) {
              throw new APIError("BAD_REQUEST", {
                error: "invalid_request",
                error_description: "This code was asked for another app.",
              });
            }

            // Checked before the redeem: a redeem of a waiting code would start its poll interval.
            if (row.status !== "approved") {
              ctx.setStatus(409);

              return ctx.json({ state: "waiting" });
            }

            let user;

            try {
              // The one-use claim: of two finishes with one cookie, one gets the row.
              ({ user } = await redeemDeviceCode({
                ctx,
                deviceCode: value,
                authorizeRedemption: async () => ({
                  ownershipWhere: { field: "clientId", value: webClient },
                  context: undefined,
                }),
                prepareRedemption: async () => undefined,
              }));
            } catch (error) {
              if (!(error instanceof APIError)) throw error;

              ctx.setCookie(deviceCookie, "", { ...half, maxAge: 0 });
              ctx.setStatus(410);

              return ctx.json({ state: "gone" });
            }

            const session = await ctx.context.internalAdapter.createSession(user.id, false, {
              signinCode: row.userCode,
              signinBrowser: row.signinBrowser,
              signinApprovedBy: row.signinApprovedBy,
            });

            await setSessionCookie(ctx, { session, user });

            ctx.setCookie(deviceCookie, "", { ...half, maxAge: 0 });

            return ctx.json({ state: "signed_in", next: row.signinNext });
          },
        ),
      },
    } satisfies BetterAuthPlugin;

    return [codes, signin] as const;
  },
});

/**
 * Better Auth's OAuth provider for MCP: `jwt()` signs the access tokens, and `mcp()` binds them
 * to the MCP resource and serves its RFC 9728 metadata. Registration is open (DCR), so every
 * client write is checked first: each redirect URI must be listed, or loopback `/callback`.
 */
export const mcpProvider = resource({
  label: "auth.mcpProvider",
  target: "scope",
  depends: {
    settings: authSettings,
    mcp: authMcp,
    api: betterAuthApi,
    jwt: jwtModule,
    provider: mcpModule,
  },
  factory: async ({ settings, mcp, api, jwt, provider }) => {
    const { APIError, createAuthMiddleware } = api;

    const loopback = /^http:\/\/(localhost|127\.0\.0\.1)(:\d+)?\/callback$/;

    const allowed = z
      .string()
      .refine((uri) => mcp.redirects.includes(uri) || (mcp.loopback && loopback.test(uri)));

    // A register names its redirect URIs at the top; an update may keep them, or name new ones.
    const writes = new Map<string, z.ZodType>([
      ["/oauth2/register", z.object({ redirect_uris: z.array(allowed).min(1) })],
      ["/oauth2/create-client", z.object({ redirect_uris: z.array(allowed).min(1) })],
      ["/admin/oauth2/create-client", z.object({ redirect_uris: z.array(allowed).min(1) })],
      [
        "/oauth2/update-client",
        z.object({ update: z.object({ redirect_uris: z.array(allowed).min(1).optional() }) }),
      ],
      [
        "/admin/oauth2/update-client",
        z.object({ update: z.object({ redirect_uris: z.array(allowed).min(1).optional() }) }),
      ],
    ]);

    // Claude Code and obelisk's mcp-run register a loopback redirect and name no application type.
    const untypedLoopback = z.object({
      application_type: z.undefined().optional(),
      redirect_uris: z.array(z.string().regex(loopback)).min(1),
    });

    /**
     * Better Auth's app-level hook: it sees every client write before the provider stores it.
     * A registration with only loopback redirects and no application type is a native client
     * (RFC 8252 7.3); Better Auth 1.7.7 would default it to web and refuse its redirect.
     */
    const clientCheck = createAuthMiddleware(async (ctx) => {
      const shape = writes.get(ctx.path ?? "");

      if (shape && !shape.safeParse(ctx.body).success) {
        throw new APIError("BAD_REQUEST", {
          error: "invalid_redirect_uri",
          error_description: "Each redirect URI must be one this server allows, and one is needed.",
        });
      }

      if (ctx.path === "/oauth2/register" && untypedLoopback.safeParse(ctx.body).success) {
        return { context: { body: { ...ctx.body, application_type: "native" } } };
      }
    });

    const plugins = [
      jwt.jwt(),
      provider.mcp({
        resource: new URL(mcp.path, settings.origin).href,
        scopes: mcp.scopes,
        loginPage: mcp.loginPage,
        consentPage: mcp.consentPage,
        // No client_credentials: every token speaks for a person.
        grantTypes: ["authorization_code", "refresh_token"],
        allowDynamicClientRegistration: true,
        allowUnauthenticatedClientRegistration: true,
        // A token is a signed JWT, checked without a store; a short life bounds a revoke.
        accessTokenExpiresIn: 300,
      }),
    ] as const;

    return { plugins, clientCheck };
  },
});

import { extension, tag } from "@tinker/core";
import { z } from "zod";

export const authSettings = tag({
  label: "auth.settings",
  parse: z.object({ origin: z.url({ protocol: /^https?$/ }), secret: z.string().min(32) }),
});

/**
 * OAuth for the app's MCP server: its path on the origin, the scopes a token may hold, and the
 * redirect URIs a client may register (the listed ones, and loopback `/callback` when on).
 * The default fits Claude; an app binds its own to change it.
 */
export const authMcp = tag({
  label: "auth.mcp",
  parse: z.object({
    path: z.string().regex(/^\//),
    scopes: z.array(z.string().min(1)).min(1),
    redirects: z.array(z.url()),
    loopback: z.boolean(),
    loginPage: z.string().regex(/^\//),
    consentPage: z.string().regex(/^\//),
  }),
  default: {
    path: "/mcp",
    scopes: ["mcp", "offline_access"],
    redirects: [
      "https://claude.ai/api/mcp/auth_callback",
      "https://claude.com/api/mcp/auth_callback",
    ],
    loopback: true,
    loginPage: "/signin",
    consentPage: "/consent",
  },
});

/**
 * Better Auth's rate limiter: on in production by its own default, off elsewhere. Bind
 * `{ enabled: true }` to turn it on anywhere (a test of the limits does); `false` turns it off.
 */
export const authRateLimit = tag({
  label: "auth.rateLimit",
  parse: z.object({ enabled: z.boolean().optional() }),
  default: {},
});

/** Check the required auth config before serving. */
export const authStartup = extension({
  label: "auth",
  hooks: {
    async start(event) {
      event.resolve(authSettings);

      await event.next();
    },
  },
});

import { operation, resource } from "@tinker/core";
import { z } from "zod";

import { raise } from "~/components/errors";

import { auth } from "./auth.server";
import { mcpCaller } from "./mcp.server";
import { codeSeconds, webClient } from "./plugins.server";

/** The code's row, with the code sign-in's own columns. */
type Waiting = {
  id: string;
  userCode: string;
  userId: string | null;
  status: string;
  expiresAt: Date;
  signinBrowser: string | null;
  /** The OAuth client a start from the login page names; none for a plain sign-in. */
  signinClient: string | null;
};

type CodeSession = {
  id: string;
  token: string;
  userId: string;
  createdAt: Date;
  expiresAt: Date;
  signinCode: string | null;
  signinBrowser: string | null;
  signinApprovedBy: string | null;
};

/** A code was asked for one code life before it ends. */
const codeMs = codeSeconds * 1000;

/**
 * Ten wrong codes in 15 minutes lock one caller's approvals, as obelisk did for its one owner.
 * Many users share this server, so one caller's misses lock only that caller; 100 misses from
 * everyone lock all approvals, a stop for a guess across many accounts (20^8 codes).
 */
const missWindowMs = 900_000;

const callerCap = 10;

const everyoneCap = 100;

/** This process's wrong codes: when each came, by Core's clock, for each caller and for all. */
const signinMisses = resource({
  label: "auth.signinMisses",
  target: "scope",
  factory: () => {
    const byCaller = new Map<string, number[]>();

    let everyone: number[] = [];

    return {
      locked(userId: string, now: number) {
        everyone = everyone.filter((at) => now - at < missWindowMs);

        const own = (byCaller.get(userId) ?? []).filter((at) => now - at < missWindowMs);

        byCaller.set(userId, own);

        return own.length >= callerCap || everyone.length >= everyoneCap;
      },
      miss(userId: string, now: number) {
        everyone.push(now);

        byCaller.set(userId, [...(byCaller.get(userId) ?? []), now]);
      },
    };
  },
});

export const approveSigninInput = z.object({ code: z.string().max(20) });

export const listSigninsInput = z.object({});

export const endSigninInput = z.object({ id: z.string().max(40) });

/**
 * The caller approves a code that a browser shows: that browser signs in as the caller. Case,
 * spaces, and the dash do not matter. One approve wins a race: the write checks the row still
 * waits.
 */
export const approveSignin = operation({
  label: "auth.approveSignin",
  input: approveSigninInput,
  depends: { auth, caller: mcpCaller, misses: signinMisses },
  run: async ({ auth, caller, misses }, { input, clock }) => {
    const now = clock.currentTimeMillis();

    if (misses.locked(caller.userId, now)) {
      raise("Refused", {
        message: "Too many wrong codes. Wait 15 minutes, then ask for a new code.",
      });
    }

    const { adapter } = await auth.$context;

    // No user code is empty, so a code of no letters finds no row.
    const row = await adapter.findOne<Waiting>({
      model: "deviceCode",
      where: [
        { field: "userCode", value: input.code.toUpperCase().replace(/[^A-Z]/g, "") },
        { field: "clientId", value: webClient },
      ],
    });

    // The row's end is Better Auth's own time, so it is read by the wall clock it was set with.
    if (!row || row.expiresAt <= new Date()) {
      misses.miss(caller.userId, now);

      raise("Refused", {
        message: `No sign-in waits for code "${input.code.slice(0, 12)}". A code works for 10 minutes; ask for the code on the page again.`,
      });
    }

    const shown = `${row.userCode.slice(0, 4)}-${row.userCode.slice(4)}`;

    // The write is its own guard: it changes the row only while it still waits.
    const approved = await adapter.incrementOne<Waiting>({
      model: "deviceCode",
      where: [
        { field: "id", value: row.id },
        { field: "status", value: "pending" },
      ],
      increment: {},
      set: { status: "approved", userId: caller.userId, signinApprovedBy: caller.clientId },
    });

    if (!approved) raise("Refused", { message: `Code ${shown} is already approved.` });

    const asked = new Date(row.expiresAt.getTime() - codeMs).toISOString().slice(11, 16);

    const what = row.signinClient ? `"Allow access" for ${row.signinClient}` : "sign-in";

    // An "Allow access" code gives that browser a session too: the OAuth request resumes on it.
    const grants = row.signinClient
      ? ` It signs that browser in as you and allows ${row.signinClient} to act for you.`
      : "";

    return {
      text: `Approved code ${shown} (${row.signinBrowser ?? "a browser"}, ${what}, asked at ${asked} UTC).${grants} That page goes on by itself within a few seconds. The code is used up once it does.`,
    };
  },
});

/**
 * The codes the caller approved that still wait, a count of the other live codes, and the
 * caller's own code sign-ins. Many users share one server, so the others get no detail.
 */
export const listSignins = operation({
  label: "auth.listSignins",
  input: listSigninsInput,
  depends: { auth, caller: mcpCaller },
  run: async ({ auth, caller }) => {
    const { adapter } = await auth.$context;

    const now = new Date();

    const rows = await adapter.findMany<Waiting>({
      model: "deviceCode",
      where: [
        { field: "clientId", value: webClient },
        { field: "expiresAt", operator: "gt", value: now },
      ],
    });

    // Only an approved row has an owner: the caller who approved it.
    const own = rows.filter((row) => row.userId === caller.userId);

    const waiting = own.map((row) => ({
      at: new Date(row.expiresAt.getTime() - codeMs).toISOString(),
      browser: row.signinBrowser ?? "a browser",
      kind: row.signinClient ? ("oauth" as const) : ("web" as const),
      approved: true,
      code: `${row.userCode.slice(0, 4)}-${row.userCode.slice(4)}`,
    }));

    const others = rows.length - own.length;

    const sessions = await adapter.findMany<CodeSession>({
      model: "session",
      where: [{ field: "userId", value: caller.userId }],
    });

    const active = sessions
      .filter((session) => session.signinCode && session.expiresAt > now)
      .map((session) => ({
        id: session.id,
        at: session.createdAt.toISOString(),
        browser: session.signinBrowser ?? "a browser",
        code: `${session.signinCode?.slice(0, 4)}-${session.signinCode?.slice(4)}`,
        approvedBy: session.signinApprovedBy,
      }));

    const codes = waiting.length
      ? waiting
          .map(
            (item) =>
              `${item.code} (${item.browser}, ${item.kind === "oauth" ? "Allow access" : "sign-in"}, asked ${item.at.slice(11, 16)} UTC, approved by you)`,
          )
          .join("; ")
      : "none";

    const signedIn = active.length
      ? active
          .map(
            (item) =>
              `${item.id}: ${item.browser}, since ${item.at.slice(0, 16).replace("T", " ")} UTC (code ${item.code})`,
          )
          .join("; ")
      : "none";

    return {
      text: `Waiting codes you approved: ${codes}. Other codes waiting: ${others}.\nSigned in with a code: ${signedIn}.`,
      data: { waiting, others, active },
    };
  },
});

/**
 * End one of the caller's code sign-ins. The delete goes through Better Auth, so the session
 * delete hooks speak (the sync notice and the account notice), as a sign-out does.
 */
export const endSignin = operation({
  label: "auth.endSignin",
  input: endSigninInput,
  depends: { auth, caller: mcpCaller },
  run: async ({ auth, caller }, { input }) => {
    const { adapter, internalAdapter } = await auth.$context;

    const session = await adapter.findOne<CodeSession>({
      model: "session",
      where: [
        { field: "id", value: input.id },
        { field: "userId", value: caller.userId },
      ],
    });

    if (!session?.signinCode) {
      raise("Refused", {
        message: `No code sign-in "${input.id}". List the code sign-ins to see their ids.`,
      });
    }

    await internalAdapter.deleteSession(session.token);

    return { text: `Ended sign-in ${input.id}: that browser must sign in again.` };
  },
});

import { operation, resource } from "@tinker/core";
import type { Operation } from "@tinker/core";

import { database } from "~/components/database-sqlite/index.server";
import { raise } from "~/components/errors";
import { backendStop, requestStop, startRequests } from "~/components/requests";
import { notifications, streamCursor, streamRequest } from "~/components/sync-sqlite/index.server";
import type { Sync, Stream } from "~/components/sync-sqlite/index.server";

import { liveAccount } from "./auth.server";
import readFrameRows from "./queries/read_frame.sql";

/** One replay page owns its database read and encoded bytes. */
const readFrame = operation({
  label: "sync.frame",
  depends: { database },
  run: async ({ database }, { input }: Operation.Ctx<Stream.Cursor>): Promise<Stream.Frame> => {
    const next = { public: input.public, private: input.private ? { ...input.private } : null };
    const own = next.private ?? { accountId: "", revision: 0 };

    // One read on the read connection; an empty account name matches no stream.
    const rows = readFrameRows.runSync(database.reader, {
      public: next.public,
      account: own.accountId,
      after: own.revision,
    });

    const events: Sync.Event[] = [];

    for (const row of rows) {
      events.push({
        stream: row.stream,
        revision: row.revision,
        executionId: row.execution_id,
        payload: JSON.parse(row.payload) as Sync.Payload,
      });

      if (row.stream === "public") next.public = row.revision;
      else if (next.private) next.private.revision = row.revision;
    }

    const encoder = new TextEncoder();
    return {
      cursor: next,
      count: events.length,
      bytes: events.length
        ? encoder.encode(
            `event: changes\nid: ${JSON.stringify(next)}\ndata: ${JSON.stringify({ kind: "changes", events })}\n\n`,
          )
        : new Uint8Array(),
    };
  },
});

/** The request owns one subscription, identity lease, and shared account recheck. */
const streamLease = resource({
  label: "sync.streamLease",
  target: "session",
  depends: { notifications, account: liveAccount.controller, backendStop, requestStop },
  factory: async (
    { notifications, account, backendStop, requestStop },
    { signal: cleanup, defer, clock },
  ) => {
    const stop = new AbortController();
    const signal = AbortSignal.any([stop.signal, backendStop, requestStop, cleanup]);
    const done = Symbol("sync.waitDone");
    let subscription: Awaited<ReturnType<typeof notifications.subscribe>> | undefined;
    let expectedAccount: string | null = null;
    let deadline = Infinity;
    let changed = false;
    let checking: Promise<number> | undefined;

    defer(() => lease.close());

    const lease = {
      signal,
      get changed() {
        return changed;
      },
      async open(initial: Stream.Cursor) {
        expectedAccount = initial.private?.accountId ?? null;
        subscription = await notifications.subscribe(stop.abort.bind(stop, done), expectedAccount);
        if (signal.aborted) {
          notifications.close(subscription);
          raise("Cancelled", {});
        }

        const current = await account.run();
        if (initial.private && initial.private.accountId !== current) raise("StreamDenied", {});
        deadline = clock.currentTimeMillis() + 30_000;
        if (current !== expectedAccount) subscription.stale = true;
      },
      async check(): Promise<number> {
        if (!subscription) raise("StreamDisconnected", {});
        if (notifications.ended(subscription) || clock.currentTimeMillis() >= deadline) {
          lease.close();
          return notifications.revision();
        }

        if (checking) return checking;
        if (!subscription.stale) return notifications.revision();
        subscription.stale = false;
        checking = account
          .run()
          .then((current) => {
            if (!signal.aborted && current !== expectedAccount) {
              changed = true;
              stop.abort(done);
            }
            return notifications.revision();
          })
          .finally(() => {
            checking = undefined;
          });
        return checking;
      },
      async wait(after: number) {
        await lease.check();
        if (signal.aborted) return false;
        if (!subscription) raise("StreamDisconnected", {});

        const heartbeat = await notifications.wait(subscription, after, deadline);
        await lease.check();
        return heartbeat;
      },
      revision() {
        return notifications.revision();
      },
      close() {
        if (subscription) notifications.close(subscription);
        stop.abort(done);
      },
    };
    return lease;
  },
});

type Read =
  | { kind: "ended" }
  | { kind: "idle"; wake: number }
  | { kind: "frame"; bytes: Uint8Array };

/** One request advances its cursor; cached frame values are never changed or handed to the body. */
const streamReader = resource({
  label: "sync.streamReader",
  target: "session",
  depends: { lease: streamLease, notifications, requests: startRequests },
  factory: async ({ lease, notifications, requests }) => {
    const frame = requests.scope.controller(readFrame);
    let cursor: Stream.Cursor = { public: 0, private: null };
    let afterWake = -1;
    return {
      async open(initial: Stream.Cursor) {
        await lease.open(initial);
        cursor = { ...initial, private: initial.private ? { ...initial.private } : null };
      },
      async read(): Promise<Read> {
        const wake = await lease.check();
        if (lease.signal.aborted) return { kind: "ended" };
        if (wake === afterWake) return { kind: "idle", wake };
        const privateKey = cursor.private
          ? `${cursor.private.accountId.length}:${cursor.private.accountId}:${cursor.private.revision}`
          : "-";
        const next = await notifications.share(
          `${cursor.public}:${privateKey}`,
          frame.settle.bind(frame),
          cursor,
        );
        await lease.check();
        if (lease.signal.aborted) return { kind: "ended" };

        if (!next.count) {
          afterWake = wake;
          return { kind: "idle", wake };
        }
        if (next.count < 100) afterWake = wake;
        cursor = next.cursor;
        return { kind: "frame", bytes: next.bytes.slice() };
      },
    };
  },
});

/** The request owns pulls and its independent watch loop, even when the client stops reading. */
export const eventStream = resource({
  label: "sync.stream",
  target: "session",
  depends: { lease: streamLease, reader: streamReader },
  factory: async ({ lease, reader }, { defer }) => {
    const encoder = new TextEncoder();
    const accountChange = encoder.encode('event: account\ndata: {"kind":"account-change"}\n\n');
    let output: ReadableStreamDefaultController<Uint8Array> | undefined;
    let ended = false;
    let watching: Promise<void> | undefined;
    let activity = Promise.withResolvers<boolean>();

    const close = () => {
      if (ended) return;
      ended = true;
      activity.resolve(false);

      if (lease.changed) output?.enqueue(accountChange.slice());
      output?.close();
      lease.close();
    };

    lease.signal.addEventListener("abort", close, { once: true });
    defer(async () => {
      close();
      lease.signal.removeEventListener("abort", close);
      await watching;
    });

    return {
      async open(initial: Stream.Cursor) {
        await reader.open(initial);
        let greeted = false;
        return new ReadableStream<Uint8Array>(
          {
            start(controller) {
              output = controller;
              if (ended) {
                controller.close();
                return;
              }
              watching = Promise.resolve()
                .then(async () => {
                  while (!ended) {
                    const wake = await lease.check();
                    if (ended) return;
                    const heartbeat = await lease.wait(wake);

                    const waiting = activity;
                    activity = Promise.withResolvers<boolean>();
                    waiting.resolve(heartbeat);
                  }
                })
                .catch((error) => {
                  if (lease.signal.aborted) {
                    close();
                    return;
                  }
                  ended = true;
                  activity.resolve(false);
                  output?.error(error);
                  lease.close();
                });
            },
            pull(controller) {
              return Promise.resolve()
                .then(async () => {
                  while (!ended) {
                    const awake = activity.promise;
                    const frame = await reader.read();
                    if (frame.kind === "ended") return;
                    if (frame.kind === "frame") {
                      controller.enqueue(frame.bytes);
                      return;
                    }
                    if (lease.revision() !== frame.wake) continue;
                    if (!greeted) {
                      greeted = true;
                      controller.enqueue(encoder.encode(": connected\n\n"));
                      return;
                    }

                    const heartbeat = await awake;
                    await lease.check();
                    if (!heartbeat) continue;
                    if (!ended) controller.enqueue(encoder.encode(": heartbeat\n\n"));
                    return;
                  }
                })
                .catch((error) => {
                  if (lease.signal.aborted) {
                    close();
                    return;
                  }
                  ended = true;
                  activity.resolve(false);
                  output?.error(error);
                  lease.close();
                });
            },
            cancel() {
              output = undefined;
              close();
            },
          },
          { highWaterMark: 0 },
        );
      },
    };
  },
});

/** A reconnect cursor wins over the query cursor; both are checked before opening the body. */
export const openSync = operation({
  label: "sync.open",
  input: (raw: unknown) => {
    const request = streamRequest.parse(raw);
    const supplied = request.lastEventId || new URLSearchParams(request.search).get("cursor");
    return {
      cursor: streamCursor.parse(supplied ? JSON.parse(supplied) : { public: 0, private: null }),
    };
  },
  depends: { stream: eventStream },
  run: async ({ stream }, { input }) => stream.open(input.cursor),
});
